insert into public.site_settings(id,data) values (1,'{"name": "El Arte Gráfico", "tagline": "Trading · Educación · Comunidad", "heroTitle": "Aprende a leer el gráfico como lo hace El Arte Gráfico", "heroText": "Aprende a leer el gráfico con un método claro: estructura, zonas, stop loss y gestión del riesgo, con práctica en gráficas reales.", "cards": [{"title": "Método propio", "text": "Aprendes la forma de operar de El Arte Gráfico, paso a paso y con reglas claras."}, {"title": "Gráficas reales", "text": "Practicas marcando zona y stop loss en momentos reales del mercado, en la temporalidad que pida cada ejercicio."}, {"title": "Repetición del mercado", "text": "Al confirmar, la gráfica avanza vela por vela y ves qué habría pasado con tu operación."}, {"title": "Comunidad", "text": "Noticias, actualizaciones y conversación con otros alumnos premium."}], "steps": [{"title": "Mira la lección", "text": "Video y explicación de cada regla."}, {"title": "Marca zona y stop loss", "text": "Marca tu zona y tu stop loss como lo harías en tu plataforma."}, {"title": "Mira la repetición", "text": "El mercado avanza y ves tu resultado en R."}], "premiumTitle": "Hazte premium", "premiumText": "Acceso completo a todas las lecciones, ejercicios ilimitados, práctica libre, ranking y comunidad.", "premiumItems": ["Todos los módulos y lecciones", "Ejercicios con zona, SL y repetición", "Práctica libre ilimitada", "Noticias y comunidad para premium"], "contact": "", "social": "", "legal": "El Arte Gráfico Academy es contenido educativo. Operar índices sintéticos y otros instrumentos financieros implica un alto riesgo de pérdida. Ningún ejercicio, resultado pasado ni simulación garantiza resultados futuros. No es asesoría financiera.", "markets": [{"cat": "Sintéticos", "name": "Boom y Crash", "status": "Disponible", "text": "10 índices con práctica en gráficas reales."}, {"cat": "Sintéticos", "name": "Step Index", "status": "Próximamente", "text": "Movimientos en escalones de tamaño fijo."}, {"cat": "Sintéticos", "name": "Volatility Index", "status": "Próximamente", "text": "Volatilidad constante, 24/7."}, {"cat": "Forex", "name": "Pares de divisas", "status": "Próximamente", "text": "EUR/USD, GBP/USD, USD/JPY y más."}, {"cat": "Metales", "name": "Oro (XAU/USD)", "status": "Próximamente", "text": "El activo refugio por excelencia."}]}'::jsonb) on conflict (id) do update set data=excluded.data;
