insert into public.posts(id,title,body,image_url,category,pinned,premium_only,allow_comments,created_at) values ('342659e2-7579-4e65-802a-440fccc2fb9c','Bienvenidos a El Arte Gráfico Academy','Esta es la sección de noticias y comunidad. Aquí publicaré actualizaciones del método, anuncios y novedades.
